// Bitmap fonts in the IBF format (spec/font-format.md). A font is either a
// file loaded into memory and opened with font_open(), which points the tables
// straight into the file, or C tables compiled into the firmware (fonts/*.c,
// generated by tools/fonttool/fonttool.py c).
//
// Glyph bitmaps: rows padded to whole bytes, MSB = leftmost pixel, 1 = ink.
// Advances and kerning are in 1/64 px (FONT_UNIT).
#pragma once

#include <stddef.h>
#include <stdint.h>

#if defined(__BYTE_ORDER__) && __BYTE_ORDER__ != __ORDER_LITTLE_ENDIAN__
#error "IBF tables are little-endian and used in place"
#endif

#define FONT_UNIT 64            // 1/64 px per px
#define FONT_STYLE_BOLD 1
#define FONT_STYLE_ITALIC 2

// These three match the file records byte for byte (spec 3.2 to 3.4).
typedef struct {
    uint32_t first_cp;
    uint16_t count;
    uint16_t first_glyph;
} font_range_t;

typedef struct {
    uint32_t bitmap;   // offset into font_t.bitmaps
    uint16_t advance;  // pen advance, 1/64 px
    uint8_t width;     // bitmap box, px
    uint8_t height;
    int8_t x_off;      // box left edge relative to the pen
    int8_t y_off;      // box top edge relative to the baseline (negative = above)
    uint16_t kern_as;  // glyph whose kerning pairs this one uses (its own index if none)
} font_glyph_t;

typedef struct {
    uint16_t left, right;  // glyph indices
    int16_t value;         // 1/64 px, added to the left glyph's advance
} font_kern_t;

_Static_assert(sizeof(font_range_t) == 8, "font_range_t must match the file");
_Static_assert(sizeof(font_glyph_t) == 12, "font_glyph_t must match the file");
_Static_assert(sizeof(font_kern_t) == 6, "font_kern_t must match the file");

typedef struct {
    char name[33];
    uint8_t style;       // FONT_STYLE_*
    uint16_t pixel_size;
    uint16_t line_height;  // baseline to baseline, px
    uint16_t ascent;       // px above the baseline
    uint16_t descent;
    uint16_t x_height;
    uint16_t range_count;
    uint32_t glyph_count;
    uint32_t kern_count;
    const font_range_t *ranges;
    const font_glyph_t *glyphs;
    const font_kern_t *kerns;
    const uint8_t *bitmaps;
    uint32_t fallback;   // glyph index of U+FFFD
} font_t;

typedef enum {
    FONT_OK = 0,
    FONT_ERR_SHORT,      // shorter than the header, or a table outside the file
    FONT_ERR_MAGIC,
    FONT_ERR_VERSION,    // unknown major version, header size or bpp
    FONT_ERR_CRC,
    FONT_ERR_ALIGN,      // the data or a table isn't 4-byte aligned
    FONT_ERR_TABLES,     // ranges, glyphs or kerning pairs inconsistent
    FONT_ERR_REQUIRED,   // U+0020, U+002D or U+FFFD missing
} font_err_t;

// Checks a font file (validator rules 1 to 6) and sets *font to point into it.
// `data` must be 4-byte aligned and stay valid while the font is used.
font_err_t font_open(font_t *font, const uint8_t *data, size_t len);
const char *font_strerror(font_err_t err);

// Glyph index for a codepoint, or -1.
int32_t font_index(const font_t *font, uint32_t cp);
// Glyph index for a codepoint, or the U+FFFD glyph.
uint32_t font_index_or_fallback(const font_t *font, uint32_t cp);
// Glyph for a codepoint, or the U+FFFD glyph.
const font_glyph_t *font_glyph(const font_t *font, uint32_t cp);
// Kerning between two neighbouring glyphs (indices), 1/64 px. Spec 3.4.
int32_t font_kern(const font_t *font, uint32_t left, uint32_t right);
// Width of UTF-8 text in 1/64 px, with kerning.
int32_t font_text_width(const font_t *font, const char *utf8);

// Decodes one UTF-8 sequence and advances *s. Returns 0 at the end of the
// string and U+FFFD for malformed input.
uint32_t utf8_next(const char **s);
// The same for text with a length: stops at `end` (returns 0 there).
uint32_t utf8_next_n(const char **s, const char *end);

extern const font_t font_ui16;
extern const font_t font_ui12;
